(* [comment removed for export] *)
Definition ugl_exit (ra sp gp tp t0 t1 s0 s1 a1 a3 a4 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (t2' a0' a2' a5' a6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2' s0 s1 a0' a1 a2' a3 a4 a5' a6' a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xb42bc) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma ugl_rows : forall (k : nat) (i : Z)
    (ra sp gp tp t0 s0 s1 a3 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : mem) (dh dwpl P DR dn : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 -> 0 < dwpl <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> P mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> DR <= P + 4 * (dwpl * i') /\ P + 4 * (dwpl * i') + 4 <= DR + dn) ->
  wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (ugl_exit ra sp gp tp t0 (Z_to_bv 64 2147450880) s0 s1 (Z_to_bv 64 (dwpl * 4)) a3 (Z_to_bv 64 0) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m DR dn)
    (MS (mkR ra sp gp tp t0 (Z_to_bv 64 2147450880) (Z_to_bv 64 (dh - i)) s0 s1 (Z_to_bv 64 (P + 4 * (dwpl * i))) (Z_to_bv 64 (dwpl * 4))
             (Z_to_bv 64 (P + 4 * (dwpl * i))) a3 (Z_to_bv 64 0) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xb44fc) fc None m (seg_rom asegs)).
