(* [comment removed for export] *)
Definition ugw_rows_exit (ra sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 s5 s6 s7 s8 s9 s10 s11 t4 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (s0' s1' a0' a7' s2' s3' s4' t3' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0' s1' a0' a1 a2 a3 a4 a5 a6 a7' s2' s3' s4' s5 s6 s7 s8 s9 s10 s11 t3' t4 t5' t6')
             F (Z_to_bv 64 0xb42b8) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma ugw_rows : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t2 s0 s1 a0 a2 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t6 : word) F fc (m : mem) (dh dwpl n Q DR dn : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 -> 0 < dwpl <= 2^24 -> dwpl * dh <= 2^24 -> 1 <= n < 2^26 ->
  0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> Q mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> DR <= Q + 4 * (dwpl * i') /\ Q + 4 * (dwpl * i') + 4 * n <= DR + dn) ->
  wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (ugw_rows_exit ra sp gp tp t0 (Z_to_bv 64 2147450880) t2 (Z_to_bv 64 (dwpl * 4)) a2 (Z_to_bv 64 dh) (Z_to_bv 64 0) a5 (Z_to_bv 64 n)
               s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 1) F fc m DR dn)
    (MS (mkR ra sp gp tp t0 (Z_to_bv 64 2147450880) t2 s0 s1 a0 (Z_to_bv 64 (dwpl * 4)) a2 (Z_to_bv 64 dh) (Z_to_bv 64 0) a5 (Z_to_bv 64 n)
             (Z_to_bv 64 (Q + 4 * (dwpl * i))) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 i) (Z_to_bv 64 1) (Z_to_bv 64 (Q + 4 * (dwpl * i))) t6)
        F (Z_to_bv 64 0xb4224) fc None m (seg_rom asegs)).
Proof.
